import sqlite3
import struct
from datetime import datetime, timezone
from contextlib import asynccontextmanager
from typing import Optional

from fastapi import FastAPI, UploadFile, File, Form, HTTPException
from fastapi.responses import Response
import uvicorn

DATABASE = "db.sqlite3"


def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    conn.execute("""
        CREATE TABLE IF NOT EXISTS photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            filename TEXT,
            content_type TEXT,
            image_data BLOB,
            note TEXT,
            city TEXT NOT NULL,
            uploaded_at TEXT NOT NULL
        )
    """)
    conn.commit()
    conn.close()


@asynccontextmanager
async def lifespan(app: FastAPI):
    init_db()
    yield


app = FastAPI(lifespan=lifespan)


# ----------------------------------------------------------------------
# Image sanitization – strip invisible metadata (PNG and JPEG)
# ----------------------------------------------------------------------
def sanitize_png(data: bytes) -> bytes:
    """Keep only critical and non‑metadata ancillary chunks."""
    if data[:8] != b'\x89PNG\r\n\x1a\n':
        raise ValueError("Not a valid PNG")
    metadata_chunks = {
        b'tEXt', b'zTXt', b'iTXt', b'eXIf', b'tIME',
        b'sTER', b'pCAL', b'sCAL', b'gIFg', b'gIFx',
        b'gIFt', b'oFFs', b'fRAc',
    }
    chunks = []
    pos = 8
    while pos < len(data):
        if pos + 8 > len(data):
            break
        length = struct.unpack('>I', data[pos:pos+4])[0]
        chunk_type = data[pos+4:pos+8]
        chunk_len = 12 + length
        if pos + chunk_len > len(data):
            break
        if chunk_type not in metadata_chunks:
            chunks.append(data[pos:pos+chunk_len])
        pos += chunk_len
    return data[:8] + b''.join(chunks)


def sanitize_jpeg(data: bytes) -> bytes:
    """Strip APP1 (EXIF/XMP) and COM (comment) segments."""
    if data[:2] != b'\xff\xd8':
        raise ValueError("Not a valid JPEG")
    out = bytearray()
    out.extend(data[:2])  # SOI
    pos = 2
    while pos < len(data):
        if pos + 1 >= len(data) or data[pos] != 0xFF:
            break
        marker = data[pos+1]
        # SOI (should not appear again)
        if marker == 0xD8:
            out.extend(data[pos:pos+2])
            pos += 2
            continue
        # EOI
        if marker == 0xD9:
            out.extend(data[pos:pos+2])
            pos += 2
            break
        # RSTn
        if 0xD0 <= marker <= 0xD7:
            out.extend(data[pos:pos+2])
            pos += 2
            continue
        # Markers with a length field (APP, DQT, DHT, SOF, etc.)
        if pos + 4 > len(data):
            break
        length = struct.unpack('>H', data[pos+2:pos+4])[0]
        if pos + 2 + length > len(data):
            break
        segment = data[pos:pos+2+length]
        # SOS – entropy coded data follows
        if marker == 0xDA:
            out.extend(segment)
            pos += 2 + length
            # Scan for next marker
            start = pos
            while pos < len(data):
                if data[pos] == 0xFF:
                    if pos + 1 >= len(data):
                        break
                    nxt = data[pos+1]
                    if nxt == 0x00:      # escape sequence
                        pos += 2
                        continue
                    elif nxt == 0xFF:    # stray 0xFF
                        pos += 1
                        continue
                    else:                # real marker
                        break
                else:
                    pos += 1
            out.extend(data[start:pos])
            # pos now points to the next marker; continue outer loop
            continue
        # Skip metadata segments (APP1 and COM)
        if marker == 0xE1 or marker == 0xFE:
            pos += 2 + length
            continue
        # Keep all other segments
        out.extend(segment)
        pos += 2 + length
    return bytes(out)


def sanitize_image(data: bytes, content_type: str) -> bytes:
    """Sanitize image bytes based on magic bytes, falling back to content-type."""
    # Try to detect by magic bytes
    if data[:4] == b'\x89PNG':
        return sanitize_png(data)
    if data[:2] == b'\xff\xd8':
        return sanitize_jpeg(data)
    # Fallback: try content-type
    if content_type == "image/png":
        return sanitize_png(data)
    if content_type == "image/jpeg":
        return sanitize_jpeg(data)
    # For unsupported types, return as-is (no metadata stripping possible)
    return data


@app.post("/photos", status_code=201)
async def upload_photo(
    image: UploadFile = File(...),
    note: Optional[str] = Form(None),
    city: str = Form(...)
):
    if not city or not city.strip():
        raise HTTPException(status_code=400, detail="City is required")

    image_data = await image.read()
    if not image_data:
        raise HTTPException(status_code=400, detail="Empty image file")

    content_type = image.content_type or "application/octet-stream"
    filename = image.filename or "unknown"

    try:
        sanitized_data = sanitize_image(image_data, content_type)
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid image format")

    now = datetime.now(timezone.utc).isoformat()

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO photos (filename, content_type, image_data, note, city, uploaded_at) "
        "VALUES (?, ?, ?, ?, ?, ?)",
        (filename, content_type, sanitized_data, note, city, now)
    )
    photo_id = cursor.lastrowid
    conn.commit()
    conn.close()

    return {"photo_id": str(photo_id)}


@app.get("/photos/{photo_id}")
def get_photo(photo_id: str):
    try:
        pid = int(photo_id)
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid photo ID")

    conn = get_db()
    row = conn.execute(
        "SELECT image_data, content_type FROM photos WHERE id = ?", (pid,)
    ).fetchone()
    conn.close()

    if row is None:
        raise HTTPException(status_code=404, detail="Photo not found")

    image_data = row["image_data"]
    content_type = row["content_type"]
    try:
        sanitized = sanitize_image(image_data, content_type)
    except ValueError:
        raise HTTPException(status_code=500, detail="Stored image corrupted")

    return Response(content=sanitized, media_type=content_type)


@app.get("/photos/{photo_id}/info")
def get_photo_info(photo_id: str):
    try:
        pid = int(photo_id)
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid photo ID")

    conn = get_db()
    row = conn.execute(
        "SELECT note, city, uploaded_at FROM photos WHERE id = ?", (pid,)
    ).fetchone()
    conn.close()

    if row is None:
        raise HTTPException(status_code=404, detail="Photo not found")

    return {
        "note": row["note"],
        "city": row["city"],
        "uploaded_at": row["uploaded_at"]
    }


if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=5000)
